BLACK = "B"
NONE = ""


class Board:
    """Count territories of each player in a Go game

    Args:
        board (list[str]): A two-dimensional Go board
    """

    def __init__(self, board):
        self.board = list(board)
        self.height = len(self.board)
        self.width = len(self.board[0]) if self.board else 0

    def _valid(self, x, y):
        return 0 <= x < self.width and 0 <= y < self.height

    def territory(self, x, y):
        """Return (owner, set of (x, y)) for the territory containing (x, y)."""
        if not self._valid(x, y):
            raise ValueError('Invalid coordinate')
        if self.board[y][x] != ' ':
            return NONE, set()
        seen = {(x, y)}
        stack = [(x, y)]
        borders = set()
        while stack:
            cx, cy = stack.pop()
            for nx, ny in ((cx + 1, cy), (cx - 1, cy), (cx, cy + 1), (cx, cy - 1)):
                if not self._valid(nx, ny):
                    continue
                cell = self.board[ny][nx]
                if cell == ' ':
                    if (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
                else:
                    borders.add(cell)
        owner = borders.pop() if len(borders) == 1 else NONE
        return owner, seen

    def territories(self):
        """Return dict mapping owner ("W", "B", "") to set of coordinates."""
        result = {BLACK: set(), WHITE: set(), NONE: set()}
        visited = set()
        for y in range(self.height):
            for x in range(self.width):
                if self.board[y][x] == ' ' and (x, y) not in visited:
                    owner, area = self.territory(x, y)
                    visited |= area
                    result[owner] |= area
        return result
